 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'

export default function Profile() {
    const { user, profile, refreshProfile } = useAuth()
    const [myCommunities, setMyCommunities] = useState([])
    const [createdCommunities, setCreatedCommunities] = useState([])
    const [myPredictions, setMyPredictions] = useState([])
    const [loading, setLoading] = useState(true)
    const [activeTab, setActiveTab] = useState('overview') // overview, communities, predictions

    useEffect(() => {
        if (user) {
            loadProfileData()
        }
    }, [user])

    const loadProfileData = async () => {
        setLoading(true)
        try {
            // Load communities user is a member of
            const { data: memberData } = await supabase
                .from('community_members')
                .select(`
                    community_id,
                    communities (*)
                `)
                .eq('user_id', user.id)
                .eq('status', 'active')

            const communities = memberData?.map(m => m.communities).filter(c => c !== null) || []
            setMyCommunities(communities)

            // Load communities user created
            const { data: createdData } = await supabase
                .from('communities')
                .select('*')
                .eq('creator_id', user.id)

            setCreatedCommunities(createdData || [])

            // Load user's public predictions
            const { data: predictions } = await supabase
                .from('public_predictions')
                .select('*')
                .eq('user_id', user.id)
                .order('created_at', { ascending: false })
                .limit(10)

            setMyPredictions(predictions || [])

        } catch (error) {
            console.error('Error loading profile data:', error)
        } finally {
            setLoading(false)
        }
    }

    const formatDate = (date) => {
        return new Date(date).toLocaleDateString('en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric'
        })
    }

    if (loading) {
        return (
            <div className="text-center py-12">
                <div className="text-gray-500">Loading profile...</div>
            </div>
        )
    }

    return (
        <div className="max-w-4xl mx-auto">
            {/* Profile Header */}
            <div className="bg-white rounded-xl shadow-md p-6 mb-6">
                <div className="flex items-center gap-6">
                    <div className="w-20 h-20 bg-green-500 rounded-full flex items-center justify-center text-3xl font-bold text-white">
                        {profile?.username?.[0]?.toUpperCase() || user?.email?.[0]?.toUpperCase() || 'U'}
                    </div>
                    <div className="flex-1">
                        <h1 className="text-2xl font-bold text-gray-800">
                            {profile?.full_name || profile?.username || 'User'}
                        </h1>
                        <p className="text-gray-500">@{profile?.username || 'username'}</p>
                        <div className="flex items-center gap-4 mt-2 text-sm">
                            <span className="text-gray-600">📧 {user?.email}</span>
                            <span className="text-gray-400">•</span>
                            <span className="text-gray-600">Joined {formatDate(user?.created_at)}</span>
                        </div>
                    </div>
                    <Link 
                        to="/community/create"
                        className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition text-sm"
                    >
                        + Create Community
                    </Link>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-6 pt-6 border-t border-gray-200">
                    <div className="text-center">
                        <div className="text-2xl font-bold text-green-600">{profile?.points || 0}</div>
                        <div className="text-sm text-gray-500">Points</div>
                    </div>
                    <div className="text-center">
                        <div className="text-2xl font-bold text-green-600">{profile?.predictions_count || 0}</div>
                        <div className="text-sm text-gray-500">Predictions</div>
                    </div>
                    <div className="text-center">
                        <div className="text-2xl font-bold text-green-600">{profile?.total_likes || 0}</div>
                        <div className="text-sm text-gray-500">Total Likes</div>
                    </div>
                    <div className="text-center">
                        <div className="text-2xl font-bold text-green-600">{myCommunities.length}</div>
                        <div className="text-sm text-gray-500">Communities</div>
                    </div>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 mb-6">
                <button
                    onClick={() => setActiveTab('overview')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        activeTab === 'overview' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    📊 Overview
                </button>
                <button
                    onClick={() => setActiveTab('communities')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        activeTab === 'communities' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    🏛️ Communities ({myCommunities.length + createdCommunities.length})
                </button>
                <button
                    onClick={() => setActiveTab('predictions')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        activeTab === 'predictions' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    📊 My Predictions ({myPredictions.length})
                </button>
            </div>

            {/* Tab Content */}
            {activeTab === 'overview' && (
                <div className="space-y-4">
                    {/* Created Communities */}
                    {createdCommunities.length > 0 && (
                        <div className="bg-white rounded-xl shadow-md p-4">
                            <h3 className="font-semibold text-gray-700 mb-3">🏛️ Communities I Created</h3>
                            <div className="space-y-2">
                                {createdCommunities.map(community => (
                                    <Link 
                                        key={community.id}
                                        to={`/community/${community.id}`}
                                        className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition"
                                    >
                                        <div>
                                            <span className="font-medium">{community.name}</span>
                                            <span className="text-sm text-gray-500 ml-2">
                                                {community.member_count || 0} members
                                            </span>
                                        </div>
                                        <span className="text-sm text-green-600">
                                            +R{((community.member_count || 0) * 25).toFixed(2)} earned
                                        </span>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Member Communities */}
                    {myCommunities.length > 0 && (
                        <div className="bg-white rounded-xl shadow-md p-4">
                            <h3 className="font-semibold text-gray-700 mb-3">🏛️ Communities I've Joined</h3>
                            <div className="space-y-2">
                                {myCommunities.map(community => (
                                    <Link 
                                        key={community.id}
                                        to={`/community/${community.id}`}
                                        className="block p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition"
                                    >
                                        <span className="font-medium">{community.name}</span>
                                        <span className="text-sm text-gray-500 ml-2">
                                            {community.member_count || 0} members
                                        </span>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}

                    {createdCommunities.length === 0 && myCommunities.length === 0 && (
                        <div className="bg-white rounded-xl shadow-md p-8 text-center">
                            <div className="text-4xl mb-4">🏛️</div>
                            <p className="text-gray-500">No communities yet</p>
                            <Link 
                                to="/community/create"
                                className="inline-block mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700"
                            >
                                Create Your First Community
                            </Link>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'communities' && (
                <div className="space-y-4">
                    {/* Created Communities */}
                    {createdCommunities.length > 0 && (
                        <div className="bg-white rounded-xl shadow-md p-4">
                            <h3 className="font-semibold text-gray-700 mb-3">👑 Communities I Created</h3>
                            <div className="space-y-2">
                                {createdCommunities.map(community => (
                                    <Link 
                                        key={community.id}
                                        to={`/community/${community.id}`}
                                        className="flex items-center justify-between p-3 bg-yellow-50 rounded-lg hover:bg-yellow-100 transition border border-yellow-200"
                                    >
                                        <div>
                                            <span className="font-medium">{community.name}</span>
                                            <span className="text-sm text-gray-500 ml-2">
                                                {community.member_count || 0} members
                                            </span>
                                        </div>
                                        <span className="text-sm text-green-600 font-medium">
                                            Admin
                                        </span>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Member Communities */}
                    {myCommunities.length > 0 && (
                        <div className="bg-white rounded-xl shadow-md p-4">
                            <h3 className="font-semibold text-gray-700 mb-3">📁 Communities I've Joined</h3>
                            <div className="space-y-2">
                                {myCommunities.map(community => (
                                    <Link 
                                        key={community.id}
                                        to={`/community/${community.id}`}
                                        className="block p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition"
                                    >
                                        <span className="font-medium">{community.name}</span>
                                        <span className="text-sm text-gray-500 ml-2">
                                            {community.member_count || 0} members
                                        </span>
                                    </Link>
                                ))}
                            </div>
                        </div>
                    )}

                    {createdCommunities.length === 0 && myCommunities.length === 0 && (
                        <div className="bg-white rounded-xl shadow-md p-8 text-center">
                            <div className="text-4xl mb-4">🔍</div>
                            <p className="text-gray-500">You haven't joined any communities yet</p>
                            <Link 
                                to="/community"
                                className="inline-block mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700"
                            >
                                Discover Communities
                            </Link>
                        </div>
                    )}
                </div>
            )}

            {activeTab === 'predictions' && (
                <div>
                    {myPredictions.length === 0 ? (
                        <div className="bg-white rounded-xl shadow-md p-8 text-center">
                            <div className="text-4xl mb-4">📊</div>
                            <p className="text-gray-500">You haven't shared any predictions yet</p>
                            <Link 
                                to="/matches"
                                className="inline-block mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700"
                            >
                                Share Your First Prediction
                            </Link>
                        </div>
                    ) : (
                        <div className="space-y-3">
                            {myPredictions.map(pred => {
                                const data = pred.prediction_data || {}
                                let resultEmoji = '🤝'
                                if (data.result === 'Home Win') resultEmoji = '🏠'
                                else if (data.result === 'Away Win') resultEmoji = '✈️'

                                return (
                                    <div key={pred.id} className="bg-white rounded-xl shadow-md p-4">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-3">
                                                <span className="text-lg">{resultEmoji}</span>
                                                <span className="font-semibold">{data.result || 'Draw'}</span>
                                                <span className="text-sm text-gray-500">
                                                    🟨{data.yellowCards || 0} 🟥{data.redCards || 0}
                                                </span>
                                                <span className="text-sm text-gray-500">
                                                    🏁{data.corners || 0}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-4 text-sm">
                                                <span className="text-red-500">❤️ {pred.likes_count || 0}</span>
                                                <span className="text-gray-400">{formatDate(pred.created_at)}</span>
                                            </div>
                                        </div>
                                    </div>
                                )
                            })}
                        </div>
                    )}
                </div>
            )}
        </div>
    )
}
